def set_limits(self, low=None, high=None):
    """
    Adjust the limits on the rows retrieved. We use low/high to set these,
    as it makes it more Pythonic to use these functions. When the SQL is
    generated, they are converted to the LIMIT/OFFSET part of the query.
    """
    if high is not None:
        if self.high_mark is not None:
            self.high_mark = min(self.high_mark, self.low_mark + high)
        else:
            self.high_mark = self.low_mark + high
    if low is not None:
        if self.high_mark is not None:
            self.low_mark = min(self.high_mark, self.low_mark + low)
        else:
            self.low_mark = self.low_mark + low
```

